import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import {
  normalizeGeneratedFile,
  normalizeHeader,
} from '../../scripts/normalize-content-collections'

/** content-collections 生成头含 `new Date()`，每次构建都变，需规范化为固定串。 */
describe('normalizeHeader', () => {
  it('把带时间戳的生成头替换为固定串', () => {
    const input =
      '// generated by content-collections at Thu Oct 15 2026 15:01:41 GMT+0800\n\nconst a = 1\n'
    expect(normalizeHeader(input)).toBe('// generated by content-collections\n\nconst a = 1\n')
  })

  it('已是固定串时保持幂等', () => {
    const input = '// generated by content-collections\n\nconst a = 1\n'
    expect(normalizeHeader(input)).toBe(input)
  })

  it('无生成头时原样返回', () => {
    const input = 'const a = 1\n'
    expect(normalizeHeader(input)).toBe(input)
  })
})

/** `normalizeGeneratedFile`：读文件、规范化、仅在变化时写回，文件缺失时 no-op。 */
describe('normalizeGeneratedFile', () => {
  const tmpDirs: string[] = []

  afterEach(() => {
    for (const dir of tmpDirs.splice(0)) rmSync(dir, { recursive: true, force: true })
  })

  function writeTmp(content: string): string {
    const dir = mkdtempSync(join(tmpdir(), 'cc-normalize-'))
    tmpDirs.push(dir)
    const file = join(dir, 'index.js')
    writeFileSync(file, content)
    return file
  }

  it('把带时间戳的文件改写为固定头，并返回 true', () => {
    const file = writeTmp('// generated by content-collections at Thu Oct 15 2026\n\nconst a = 1\n')
    expect(normalizeGeneratedFile(file)).toBe(true)
    expect(readFileSync(file, 'utf-8')).toBe('// generated by content-collections\n\nconst a = 1\n')
  })

  it('已规范化时不再写回，返回 false（避免 dev 轮询死循环）', () => {
    const file = writeTmp('// generated by content-collections\n\nconst a = 1\n')
    expect(normalizeGeneratedFile(file)).toBe(false)
    expect(readFileSync(file, 'utf-8')).toBe('// generated by content-collections\n\nconst a = 1\n')
  })

  it('文件不存在时静默返回 false（首次内容构建前不抛错）', () => {
    expect(normalizeGeneratedFile(join(tmpdir(), 'cc-normalize-missing', 'index.js'))).toBe(false)
  })
})
